from rb_lib import *


def build():
    t4 = J("t4"); t5 = J("t5"); t6 = J("t6")
    # ============================================================= TASK 4
    H2("TASK 4 – WEB SERVICE SECURITY: HTTPS, CERTIFICATE VALIDATION, MUTUAL AUTHENTICATION AND HARDENING (7 marks)", True)
    H3("Task 4.1 – Working HTTPS service and client (3 marks)")
    P(f"**Service** (`run_t4.py`, Python {t4['python']} `ssl` + `http.server`, {t4['openssl']}): server certificate for `hospital.test` (SAN: hospital.test, api.hospital.test, EKU serverAuth) issued by the Issuing CA of Task 2; **minimum protocol TLS 1.2**, TLS 1.3 negotiated; **mutual TLS** for `/records/…` (the listener requests a client certificate; the handler returns **401** if none was presented and **403** if the certificate’s CN is not on the allow-list; `/status` is public); **security response headers** on every response. The client verifies the chain against the hospital root, the validity period and the **hostname** (`check_hostname`), and presents `client1` (EKU clientAuth) for the protected endpoint.")
    s = t4["s41"]
    CAPT("t4run", "Client results against the running service")
    TBL(["Request", "Negotiated", "Result"], [["GET /status (no client certificate)", f"{s['status']['protocol']}, {s['status']['cipher']} ({s['status']['bits']}-bit)", f"{s['status']['status']} – `{s['status']['body']}`"],
        ["GET /records/1001 **with** client certificate `lab-client-1`", f"{s['records_mtls']['protocol']}, {s['records_mtls']['cipher']}", f"{s['records_mtls']['status']} – `{s['records_mtls']['body']}`"],
        ["GET /records/1001 **without** client certificate", "TLS handshake completes (optional client auth)", f"{s['records_nocert']['status']} – `{s['records_nocert']['body']}`"]], [2.4, 2.1, 2.1], 8)
    P("**Certificate validation output** (client side, each step made visible; the TLS library performs the same checks internally and a failure aborts the handshake):", 9.5)
    CODE("\n".join(s["validation"]), 7.6)
    P("`openssl s_client -verify_return_error -verify_hostname hospital.test` on the same service, TLS 1.3, with the client certificate:", 9.5)
    CODE("\n".join(l.strip() for l in s["openssl_chain"]), 7.6)
    CAPT("t4hdr", "Response security headers sent by the service (observed in the response above)")
    hdr = [h for h in s["status"]["headers"] if h.split(":")[0] in ("Strict-Transport-Security", "Content-Security-Policy", "X-Content-Type-Options", "X-Frame-Options", "Cache-Control", "Referrer-Policy")]
    why = {"Strict-Transport-Security": "browser must use HTTPS for two years – defeats SSL stripping", "Content-Security-Policy": "API returns JSON only: nothing may load or frame", "X-Content-Type-Options": "no MIME sniffing of JSON into script", "X-Frame-Options": "no clickjacking", "Cache-Control": "patient data must not be cached by proxies or browsers", "Referrer-Policy": "no URL leakage to other sites"}
    TBL(["Header", "Value", "Purpose"], [[h.split(":", 1)[0], "`" + h.split(":", 1)[1].strip() + "`", why[h.split(":")[0]]] for h in hdr], [1.7, 2.3, 2.6], 8)
    P("**Server log (internal):** `" + "`, `".join(s["server_log"][1:5:1]) + "` – the denial reason is logged internally; the client sees only the status and a generic message. **Secure key handling:** the server key is a test key created at run time and read from a mode-600 file; nothing secret is printed.", 9.5)
    H3("Task 4.2 – Handshake capture (1 mark)")
    P("`openssl s_client -msg` records the handshake messages. TLS 1.2 is captured because there the __Certificate message is visible__; TLS 1.3 is captured to show where encryption starts. Message lengths are from the capture (hex → decimal). In this capture the client sent no certificate (optional authentication).")
    CAPT("t4cap12", "TLS 1.2 handshake as captured (cipher ECDHE-RSA-AES256-GCM-SHA384; server temporary key X25519, 253 bits)")
    TBL(["Dir.", "Message", "Bytes", "Contents / role", "Encrypted?"], [
        ["→", "**ClientHello**", "205", "versions, cipher-suite list, client random, extensions (SNI = hospital.test)", "no"], ["←", "**ServerHello**", "65", "chosen version TLS 1.2, cipher ECDHE-RSA-AES256-GCM-SHA384, server random", "no"],
        ["←", "**Certificate**", "1818", "server certificate chain (hospital.test + Issuing CA)", "no – visible"], ["←", "**ServerKeyExchange**", "300", "**key-exchange parameters**: ephemeral X25519 public value + RSA signature over client/server randoms and the parameters", "no"],
        ["←", "CertificateRequest", "52", "asks for a client certificate (acceptable CAs)", "no"], ["←", "ServerHelloDone", "4", "end of server flight", "no"], ["→", "Certificate (client)", "–", "empty list in this capture", "no"],
        ["→", "**ClientKeyExchange**", "37", "client’s ephemeral X25519 public value", "no"], ["→", "ChangeCipherSpec", "1", "**from here the client’s records are encrypted**", "–"], ["→", "Finished", "16 (+tag)", "MAC over the whole handshake transcript", "**yes**"],
        ["←", "NewSessionTicket, ChangeCipherSpec, Finished", "186 / 1 / 16", "server switches to encrypted records", "yes"], ["↔", "Application data", "–", "HTTP request/response", "**yes**"]], [0.35, 1.5, 0.6, 3.3, 0.85], 7.8, align=["c", "l", "c", "l", "c"])
    CAPT("t4cap13", "TLS 1.3 handshake as captured (TLS_AES_256_GCM_SHA384; server temporary key X25519, 253 bits)")
    TBL(["Dir.", "Message", "Bytes", "Contents / role", "Encrypted?"], [
        ["→", "**ClientHello**", "242", "supported versions, cipher suites, **key_share (X25519 public value)**, SNI", "no"], ["←", "**ServerHello**", "122", "chosen suite and the server’s **key_share**: **both sides can now derive the handshake keys**", "no"],
        ["←", "EncryptedExtensions", "6", "**first message under handshake traffic keys**", "**yes**"], ["←", "CertificateRequest", "45", "request for client certificate", "yes"], ["←", "**Certificate**", "1823", "server chain – **no longer visible to an observer**", "yes"],
        ["←", "CertificateVerify", "264", "signature over the transcript with the server certificate’s key (proof of possession)", "yes"], ["←", "Finished", "52", "MAC over the transcript", "yes"], ["→", "Certificate / Finished", "8 / 52", "client’s (empty) certificate list and Finished", "yes"],
        ["↔", "Application data", "–", "protected with the **application traffic keys** derived after Finished", "**yes**"]], [0.35, 1.5, 0.6, 3.3, 0.85], 7.8, align=["c", "l", "c", "l", "c"])
    FIG("t4_tls", 6.3, "TLS 1.3 with mutual authentication: the point at which encryption begins (after ServerHello) and the application keys.", "fig_tls")
    P("**Where application data becomes encrypted.** In TLS 1.2 encryption starts only after the ChangeCipherSpec that follows ClientKeyExchange, so the server certificate and the key-exchange parameters cross the network in clear. In TLS 1.3 it starts immediately after ServerHello (EncryptedExtensions onwards), so even the certificates are hidden, and HTTP data is sent under separate application keys after the Finished messages.", 9.5)
    H3("Task 4.3 – Predictions before execution, then results (1 mark)")
    CAPT("t4pred", "Four required failure cases plus one extra, with predicted and observed failing step")
    TBL(["Case", "Scenario", "Predicted", "Actual handshake", "Observed error / status"], [[t["tag"], t["desc"], t["predicted"], t["handshake"], (t["error"].split("|")[-1].strip()[:110] if t["error"] else t["status"])] for t in t4["s43"]], [0.4, 1.7, 1.8, 0.8, 1.9], 7.5, align=["c", "l", "l", "c", "l"])
    se = t4["s43_server_errors"]
    P(f"**Failing step in each case.** (a) The certificate-verification step on the client rejects the expired certificate (server-side log: __{se['expired'][0]}__ – the client sent the alert and aborted); no HTTP is exchanged. (b) With the IP address as target name the hostname check fails (‘IP address mismatch’): the chain is valid but is not for that __name__ – this is exactly the check that stops a valid certificate for another site. (c) The TLS-1.0-only server never reaches certificate verification: no common protocol version (client alert __protocol version__; server log: __{se['legacy'][0]}__). (d) With optional client authentication, the **TLS layer succeeds** and the failure is at the **application layer** (401, ‘client certificate required’) – so the protection of `/records` depends on the handler check; (d2) with required authentication the handshake itself is aborted (server log: __{se['required'][0]}__). All five predictions matched. Design lesson: choose where authentication is enforced, and never leave a protected route reachable on an optional-auth listener without a handler check.", 9.5)
    H3("Task 4.4 – Controlled downgrade / weak-cipher demonstration (1 mark)")
    d = t4["s44"]
    P("**Isolation.** The weak configuration ran only on localhost, on a test port, with the test certificate and no real data. **Weak server:** " + d["weak_server"] + ".")
    CAPT("t4down", "Downgrade lab: weak configuration, then the corrected configuration")
    TBL(["Client", "Server", "Result"], [["legacy client (TLS 1.0 only, AES128-SHA)", "**weak** configuration", f"handshake {d['legacy_client_vs_weak']['handshake']}: **{d['legacy_client_vs_weak']['protocol']}, {d['legacy_client_vs_weak']['cipher']}**, {d['legacy_client_vs_weak']['status']} – the weak connection works"],
        ["legacy client (TLS 1.0 only, AES128-SHA)", "**corrected**: TLS ≥ 1.2, ECDHE + AES-GCM/ChaCha20 only", f"handshake {d['legacy_client_vs_fixed']['handshake']}: {d['legacy_client_vs_fixed']['error'].split('|')[0]} – **refused**"],
        ["modern client", "**corrected**", f"handshake {d['modern_client_vs_fixed']['handshake']}: {d['modern_client_vs_fixed']['protocol']}, {d['modern_client_vs_fixed']['cipher']}, {d['modern_client_vs_fixed']['status']}"]], [1.7, 2.0, 2.9], 8)
    P("**Risk of the original configuration.** The negotiated suite `AES128-SHA` uses RSA key transport, so there is **no forward secrecy**: anyone who records the encrypted traffic and later obtains the server’s private key can decrypt every past session; it uses CBC with a SHA-1 MAC (the family of padding-oracle and BEAST/Lucky-13-type attacks) and TLS 1.0 lacks the protections of later versions; and because the server __offers__ old versions, an on-path attacker can try to push a client down to them. The corrected configuration removes the old versions and non-AEAD, non-forward-secret suites entirely – the legacy client is **refused**, and TLS 1.3 additionally embeds a downgrade sentinel in the server random so a version-rollback is detected by clients. The price is availability for very old clients, which is recorded as accepted residual risk.", 9.5)
    H3("Task 4.5 – Extension to a mobile app and third-party laboratories (1 mark)")
    CAPT("t4ext", "Reasoned extension")
    TBL(["Topic", "Mobile appointment app", "Third-party laboratories"], [
        ["Authentication of the **client**", "A patient has no certificate: user authentication via OAuth 2.0/OIDC login with PKCE; tokens are short-lived and bound to the device; the app still authenticates the **server** by TLS (certificate pinning of the Issuing CA or public key, with a pin backup for rotation).", "**Mutual TLS** with one client certificate per laboratory, issued by the hospital CA and bound to the laboratory’s API identity (as in 4.1)."],
        ["Certificate **lifecycle**", "Server certificate renewed automatically (≈ 90 days); app pins survive renewal only if the pinned key or CA is stable – plan a pin rotation window.", "Issue on onboarding after identity proofing, **short validity (30–90 days) with automated renewal** (ACME/EST); inventory of every issued certificate."],
        ["**Authorisation**", "Server-side checks per patient record (a user may read only their own appointments) – never trust the app.", "Map certificate subject → laboratory account → allowed endpoints and record scopes (the 403 path of 4.1); least privilege per lab."],
        ["**Revocation risk**", "A stolen token or device: server-side token revocation and short lifetimes; app cannot be relied on to check OCSP.", "A compromised lab key: revoke at the Issuing CA and **enforce on the server** (CRL/OCSP stapling); because clients can be offline or lazy, prefer short-lived certificates so that the window of exposure is days, not years."],
        ["Residual risks", "Rooted devices, malware, pin-bypass tools.", "A lab’s own breach; stale CRLs; allow-list drift."]], [1.2, 2.7, 2.7], 7.9)
    BOX("Rubric check – Task 4 (7)", ["4.1 ✔ working TLS 1.3 service and client, chain/validity/hostname output, mTLS endpoint (200/401/403), six security headers.  4.2 ✔ TLS 1.2 and 1.3 captures with ClientHello, ServerHello, Certificate, key-exchange parameters and the encryption point.  4.3 ✔ four predictions + one extra, all matched, failing step identified.  4.4 ✔ isolated downgrade, corrected configuration, refusal, risk explained.  4.5 ✔ mobile and third-party extension."])

    # ============================================================= TASK 5
    H2("TASK 5 – THREE DEFENDERS, ONE MAILBOX: SPF, DKIM AND DMARC (7 marks)", True)
    P("`mailauth.py` implements the three mechanisms from scratch against a simulated DNS zone (`zone.json`, below). SPF checks the **envelope sender’s domain against the connecting IP** (`ip4`, `include`, qualifiers `+ - ~ ?`, ten-lookup limit); DKIM signs selected headers and the body (`rsa-sha256`, relaxed/relaxed canonicalisation, body hash `bh`, signature `b`) and verifies it against the **key published in DNS**; DMARC checks that the **visible From domain is aligned** with an SPF- or DKIM-authenticated domain and returns the owner’s policy. Every function returns its evidence, not only a verdict.")
    CAPT("t5zone", "Simulated DNS zone (public data only; DKIM keys abbreviated)")
    TBL(["DNS name (TXT)", "Value"], [[k, "`" + (v[:78] + "…" if len(v) > 80 else v) + "`"] for k, v in t5["zone"].items()], [2.6, 4.0], 7.8)
    msgs = t5["messages"]; m1 = msgs[0]; m3 = msgs[2]
    H3("Rubric 5-a/5-b/5-c – evidence for each mechanism (M1 legitimate, M3 mailing list)")
    CODE("M1 SPF  (ip 192.0.2.10, MAIL FROM bounce@hospital.test)\n" + "\n".join("  " + e for e in m1["spf_evidence"]) + "\nM1 DKIM\n" + "\n".join("  " + e for e in m1["dkim_evidence"]) + "\nM1 DMARC (From domain hospital.test)\n" + "\n".join("  " + e for e in m1["dmarc_evidence"]), 7.3)
    CODE("M3 DKIM (list added a footer and a subject tag after signing)\n" + "\n".join("  " + e for e in m3["dkim_evidence"]) + "\nM3 DMARC\n" + "\n".join("  " + e for e in m3["dmarc_evidence"]), 7.3)
    H3("Rubric 5-d – eight designed messages: predictions, execution and outcome table")
    CAPT("t5out", "Outcome table (prediction fixed in the program before execution; ‘match’ computed by the program)")
    TBL(["ID", "Message (sending IP, envelope sender)", "SPF", "DKIM", "DMARC", "Action", "Predicted = actual"], [[m["id"], m["title"] + f" ({m['ip']}, {m['mail_from']})", m["actual"]["spf"], m["actual"]["dkim"], m["actual"]["dmarc"], m["actual"]["action"], "✔" if m["match"] else "✘"] for m in msgs], [0.4, 3.0, 0.5, 0.5, 0.55, 0.9, 0.7], 7.6, align=["c", "l", "c", "c", "c", "c", "c"])
    FIG("t5_matrix", 5.3, "Outcome matrix for the eight test messages.", "fig_matrix")
    ni = t5["no_include"]
    H3("Rubric 5-e – analysis")
    P("**Can SPF and DKIM both pass and DMARC still fail?** Yes – **M4**: the attacker sends from his own authorised server with envelope sender `x@evil.test` (SPF **pass** for evil.test) and signs with his own key (DKIM **pass** for d=evil.test), but displays `From: lab@hospital.test`. Both authentications are real; neither is for the domain the reader sees, so alignment fails and the policy `p=reject` applies. DMARC’s contribution is precisely this link between the authenticated domain and the visible From address, which SPF and DKIM alone do not make.")
    P("**Can a legitimate message fail?** Yes – **M3**: a mailing list rewrote the subject and added a footer after the lab’s DKIM signature (body hash mismatch ⇒ DKIM fail), and the list sends from its own IP with its own envelope domain (SPF pass, but for lists.example, not aligned) ⇒ DMARC fail ⇒ **reject, although the message is genuine**. Contrast **M3b**: a list that only adds an unsigned header keeps the body and the signed headers intact and passes. **M5** (forwarding): SPF fails because the forwarder’s IP is not authorised, but the unmodified DKIM signature still verifies and is aligned ⇒ DMARC pass; this is why DKIM is the mechanism that survives forwarding. **M7** shows a limit of DMARC: content modified in transit but sent from an authorised server passes DMARC through SPF alignment although DKIM fails – DMARC is not an integrity guarantee.")
    P(f"**Third-party sender pitfall.** M6 (newsletter service) passes because the hospital’s SPF record contains `include:_spf.mailer.test` and the service signs with the hospital’s delegated key. When the `include:` is omitted (large-organisation misconfiguration) the same message gives SPF = **{ni['spf']}**, DKIM = {ni['dkim']}, DMARC = **{ni['dmarc']}** – it is rescued only by DKIM alignment, so a single mechanism should never be the only path.")
    CAPT("t5deploy", "Deployment decisions")
    TBL(["Setting", "Decision", "Reason"], [
        ["**Small company**", "Publish SPF (`-all`) for the one mail provider; enable DKIM at the provider; DMARC with `p=none` and `rua` reports first, move to `quarantine`/`reject` once reports show no legitimate source fails.", "Few sending systems; low operational risk; reports reveal forgotten sources (e.g. the website’s form mailer) before enforcement."],
        ["**Large organisation**", "Inventory every sender (ESPs, CRM, ticketing); `include:` each; DKIM per sender with its own selector and rotation; subdomain policy `sp=`; staged DMARC enforcement; watch the 10-lookup limit of SPF.", "Many third-party senders are the typical cause of DMARC failures (M6 without `include:`); selectors allow independent key rotation."],
        ["**Mailing list**", "List operators should avoid modifying signed content, or re-send under their own domain with ‘From’ rewriting; domains with `p=reject` should expect list-traffic loss (M3) and use list-friendly handling.", "DKIM breaks on modification; SPF is not aligned to the author’s domain."]], [1.2, 3.1, 2.3], 8)
    P("**Distinction from PGP and S/MIME.** SPF/DKIM/DMARC authenticate **domains and servers** – “this mail came from (or was authorised by) hospital.test” – automatically, with no user action, and the result is a __delivery policy__. PGP and S/MIME authenticate **people (end-to-end)** – “this message was signed by the holder of the key for dr.rao@…” – and add **confidentiality**; they work through any intermediary and are verifiable by a third party later. DMARC says nothing about the message’s secrecy, nothing about the individual author inside the domain, and – as M7 shows – does not by itself guarantee unaltered content. The three-defender stack and end-to-end signing therefore complement each other.", 9.5)
    BOX("Rubric check – Task 5 (7)", ["SPF ✔ implementation + evidence.  DKIM ✔ signing/verification with DNS key, signed headers, body hash.  DMARC ✔ alignment, policy and reason.  Messages ✔ eight designed messages incl. forwarding, spoofing, modified content; predictions all matched.  Analysis ✔ pass/pass but DMARC fail (M4), legitimate failure (M3), deployment for small/large/list, distinction from PGP/S/MIME."])

    # ============================================================= TASK 6
    H2("TASK 6 – SECURE MAILING AT SCALE: KEY MANAGEMENT, REVOCATION AND COST GROWTH (9 marks)", True)
    H3("Task 6.1 – Problem definition (1 mark)")
    CAPT("t6def", "Input, output, objective, constraints and required recipient-key information")
    TBL(["", "Definition"], [["**Input**", "A message M; a list of recipient addresses; the sender’s key store (SQLite table `keys`); the current time."], ["**Output**", "One protected message that only the recipients with **currently usable** keys can open, plus a report of who was included and who was skipped **with the exact reason**; or an error if nobody is usable."],
        ["**Objective**", "Encrypt the payload once; wrap the session key only for recipients whose key is ACTIVE; never silently include an expired, revoked, untrusted or unknown key."], ["**Constraints**", "Cost grows with recipients (one wrap each); message size grows by one entry per recipient; keys have lifetimes, can be revoked and rolled over; fail closed."],
        ["**Required key information per recipient key**", "`key_id`, `addr`, public key (PEM) and fingerprint, `not_before`, `not_after`, `revoked_at` (null if not revoked), and `trust` (full / marginal / none)."]], [1.6, 5.0], 8.2)
    H3("Task 6.2 – Recipient key-state model (2 marks)")
    CAPT("t6fields", "Field meanings")
    TBL(["Field", "Meaning"], [["`key_id`", "Unique record id (address + generation, e.g. `r08@clinic.test#2`)."], ["`not_before`, `not_after`", "Validity window of the key; before it ⇒ NOT_YET_VALID, after it ⇒ EXPIRED."], ["`revoked_at`", "Time at which the key was revoked; revocation **overrides** validity (a revoked key inside its dates is still blocked)."],
        ["`trust`", "Whether the key’s fingerprint has been verified (full), partially (marginal) or not (none); minimum accepted = marginal."], ["`fingerprint`", "SHA-256 of the public key; the first 8 bytes are the key ID in the message."]], [1.6, 5.0], 8.2)
    FIG("t6_states", 6.2, "Key-state machine: only ACTIVE is allowed; every other state blocks wrapping.", "fig_states")
    CAPT("t6states", "States, transitions and the allow/block rule")
    TBL(["State", "Condition (evaluated in this order)", "Allowed?", "Transition in / out"], [["REVOKED", "`revoked_at` ≤ now", "**block**", "any state → REVOKED (terminal, overrides everything)"], ["NOT_YET_VALID", "now < `not_before`", "block", "→ ACTIVE when time passes `not_before`"], ["EXPIRED", "now > `not_after`", "block", "ACTIVE → EXPIRED at `not_after`"],
        ["UNTRUSTED (new key)", "trust below the minimum", "block", "→ ACTIVE after fingerprint verification"], ["ACTIVE", "in date, not revoked, trust ≥ marginal", "**allow**", "new key issued ⇒ older ACTIVE key is superseded"], ["MISSING", "no record for the address", "block", "—"]], [1.3, 2.4, 0.8, 2.1], 8)
    P("**Rollover.** An address may hold several keys; for each address the engine takes the **newest ACTIVE** key. If the old key is already expired (or superseded) and a new key is ACTIVE, the session key is wrapped for the __new__ key only. **Session-key wrapping:** one random `Ks` encrypts the payload once (AES-256-GCM, header including all wrapped keys as AAD); each allowed recipient gets `RSA-OAEP(pub, Ks)` tagged by an 8-byte key ID. **Invalid-recipient policy:** a blocked recipient is **skipped and reported with its reason** (the message is still sent to the others); if __no__ recipient is usable the operation fails with an error; nothing is ever wrapped for a blocked key.", 9.5)
    H3("Task 6.3 – Working key-store prototype: successful and skipped recipients (2 marks)")
    r3 = t6["t63"]
    P(f"A list of ten recipients was prepared to exercise every outcome (6 active including one rollover, 1 expired, 1 revoked inside its validity period, 1 untrusted, 1 unknown address). Result: **{r3['summary_line']}**.")
    CAPT("t6run", "Prototype run: key used or exact reason for skipping")
    rows = [[a, "included – " + k] for a, k in zip(r3["valid"], r3["valid_key_ids"])] + [[a, "**skipped – " + w + "**"] for a, w in r3["skipped"]]
    TBL(["Recipient", "Outcome (key record or reason)"], rows, [2.4, 4.2], 8.2)
    P(f"**Final message size {r3['size']} bytes** (message {r3['msg_size']} B): 6 (header) + 6 × 266 (key ID 8 + length 2 + wrapped key 256) = 1,602 B of header, 12 B nonce, 4 B length, {r3['msg_size']} + 16 B ciphertext. **Public-key operations: {r3['pk_ops']}** (one per allowed recipient, none for the four skipped); **symmetric operations: {r3['sym_ops']}** (payload encrypted once). Time {r3['time_ms']:.2f} ms.", 9.5)
    H3("Task 6.4 – Hand-derived result for five recipients and actual decryption attempts (1 mark)")
    r4 = t6["t64"]
    P("**Hand derivation** (before running): Alice – ACTIVE, full trust ⇒ wrapped. Bob – `not_after` 35 days ago ⇒ EXPIRED ⇒ skipped. Carol – inside her validity dates but revoked 3 days ago ⇒ REVOKED ⇒ skipped (revocation overrides dates). Dave – old key expired, new key ACTIVE ⇒ wrapped for the **new** key only. Erin – ACTIVE, marginal trust ≥ minimum ⇒ wrapped. Expected: 3 wrapped keys, 3 public-key operations, 1 symmetric operation, message = 6 + 3×266 + 12 + 4 + 21 + 16 bytes.")
    CAPT("t6hand", "Expected result versus actual decryption attempt by each recipient (using only the public message and that person’s private key)")
    TBL(["Recipient", "State", "Expected", "Actual decryption attempt", "Match"], [[r["recipient"], r["state"], r["expected"], r["actual"], "✔" if r["match"] else "✘"] for r in r4["rows"]], [1.6, 1.2, 1.1, 2.2, 0.5], 8, align=["l", "l", "l", "l", "c"])
    exp_size = 6 + 3 * 266 + 12 + 4 + len(b"CONFIDENTIAL: results") + 16
    P(f"Actual: public-key operations = **{r4['pk']}**, symmetric = **{r4['sym']}**, size = **{r4['size']} bytes** (hand-derived {exp_size}). **Why this gives confidence.** Two independent routes agree: the state machine’s derivation, and the cryptographic outcome that the excluded parties – holding __valid private keys__ – find **no wrapped key for their key ID**, so they cannot recover Ks even though they have the full message. The refusal is a property of the message, not of a policy check in the recipient’s software. The old key held by Dave also fails, so a rollover really transfers access to the new key. The limit of this confidence: it holds for messages created __after__ the state change; copies sent earlier remain readable by their then-valid recipients.", 9.5)
    H3("Task 6.5 – Growth experiment (1 mark)")
    g = t6["t65"]; gn = t6["t65_noindex"]; gc = t6["t65_concat"]
    CAPT("t6grow", "Cost growth with recipient count (4,000-byte message; median of 3–7 runs; final implementation)")
    TBL(["Recipients n", "PK ops", "Sym ops", "Message bytes", "Time (ms)", "µs per recipient", "Encrypt-per-recipient bytes (naive)", "Naive sym ops"], [[f"{x['n']:,}", f"{x['pk']:,}", str(x["sym"]), f"{x['size']:,}", f"{x['time_ms']:.1f}", f"{x['per_recipient_ms']*1000:.0f}", f"{x['naive_bytes']:,}", f"{x['naive_sym_ops']:,}"] for x in g], [0.8, 0.6, 0.5, 0.9, 0.7, 0.8, 1.3, 0.7], 7.8, align=["c"] * 8)
    FIG("t6_growth", 6.3, "Left: message size, hybrid versus per-recipient encryption (log–log). Right: execution time of three versions of the prototype.", "fig_growth")
    P(f"**Per-recipient versus one-time work.** __One-time:__ the AES-256-GCM encryption of the payload (≈ {g[0]['sym_ms']*1000:.1f} µs for 4 KB, **identical for every n**) and the 22-byte fixed header plus 16-byte tag. __Per recipient:__ exactly one RSA-OAEP wrap (≈ {g[-1]['per_recipient_ms']*1000:.0f} µs) and **266 bytes** (measured slope {(g[-1]['size']-g[0]['size'])/(g[-1]['n']-g[0]['n']):.0f} B per recipient). Operation counts follow n exactly (public-key operations = n, symmetric = 1); message size is linear with slope 266; a 1 MB message to 100 recipients is 1,026,638 bytes hybrid versus 100,000,000 if the whole message were re-encrypted per recipient.", 9.5)
    P(f"**A defect found by measuring.** The first version of the prototype looked up each recipient by scanning the table (no index on `addr`) and built the header by repeated byte concatenation. Its time at 10,000 recipients was **{gn[-1]['time_ms']:,.0f} ms** – {gn[-1]['per_recipient_ms']*1000:.0f} µs per recipient against {gn[0]['per_recipient_ms']*1000:.0f} µs at n = 1 – i.e. super-linear. Adding an index brought it to {gc[-1]['time_ms']:,.0f} ms, and replacing the concatenation by a single join to **{g[-1]['time_ms']:,.0f} ms** ({g[-1]['per_recipient_ms']*1000:.0f} µs per recipient, flat from n = 1 to 10,000). The cryptography was never the problem: the growth in cost came from key __management__ (lookup) and message __assembly__, not from RSA. (Note: 60 distinct RSA-2048 key pairs are reused round-robin as key material for the large lists; addresses and key IDs are distinct.)", 9.5)
    H3("Task 6.6 – Strategy for 200,000 subscribers (1 mark)")
    s6 = t6["t66"]; one = g[0]["size"]
    P(f"**What changes.** The requirement is no longer ‘a few named readers’ but a newsletter to **200,000** people, who do not need protection __from one another__. Extrapolating the measured per-recipient cost: a single multi-recipient envelope needs 200,000 wraps (≈ {s6['total_s']:.0f} s of CPU, acceptable) but its header alone is **{s6['header_bytes']/1e6:.1f} MB**, and every subscriber would have to receive all of it – about **{s6['header_bytes']*200000/1e12:.1f} TB** of delivery per issue. The cost problem has moved from cryptography to **size, delivery and key management**.")
    CAPT("t6options", "Alternatives for 200,000 subscribers (4,000-byte issue)")
    TBL(["Strategy", "Size / cost (measured basis)", "Security properties"], [
        ["**A.** One envelope with 200,000 wrapped keys", f"{s6['header_bytes']/1e6:.1f} MB header; ≈ {s6['total_s']:.0f} s CPU; ≈ {s6['header_bytes']*200000/1e12:.1f} TB total delivery", "unchanged per-recipient confidentiality – but not deliverable"],
        ["**B.** One envelope per subscriber", f"{one:,} B each → {200000*one/1e6:,.0f} MB total; 200,000 wraps; payload encrypted once, re-assembled per subscriber", "full per-recipient control and revocation; works with the existing prototype; bandwidth is linear in subscribers"],
        ["**C.** One encrypted issue + **group (content) key**, delivered through an authenticated channel (TLS portal / key service); membership changes re-key the group (tree-based schemes need ≈ log₂ 200,000 ≈ 18 wraps per change)", "issue stored once (≈ 4 KB); per-subscriber work moves to key distribution", "**weakened:** all subscribers share the key, so one subscriber can leak it (no confidentiality __between__ subscribers, no per-recipient forward secrecy); revocation takes effect only at the next re-key; sender authenticity can still be kept with **one** signature over the issue"]], [2.4, 2.1, 2.1], 7.9)
    P("**Recommended:** B for small-to-medium lists and C for the 200,000-subscriber case, with one signature per issue (O(1)) and the group key delivered over TLS. The decision is an explicit trade: confidentiality __among__ subscribers and instant revocation are given up in exchange for a deliverable system; everything that remains (who may read, when keys change) still depends on key management.", 9.5)
    H3("Task 6.7 – Technical reflection (≤ 150 words) (1 mark)")
    refl = ("In the prototype the cryptography scaled perfectly: one payload encryption, one 266-byte wrap per recipient, 0.044 ms each at 10,000 recipients. What failed was key management. A missing index and naive assembly made the first version super-linear, and the five-recipient test showed that every decision (expired, revoked, untrusted, superseded) is a state held outside the cipher. Revoked or expired recipients could not decrypt only because no key was wrapped for them; nothing in RSA or AES made that decision. At 200,000 subscribers the real costs became message size, delivery and who holds which key. Algorithms protect data only while keys are generated, verified, rotated and revoked correctly, so key management stays necessary.")
    nw = len(refl.split()); assert nw <= 150, nw
    P(refl); P(f"__({nw} words)__", 8.5, align="l")
